59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
110	        validateRequiredFields(ownerFieldsDto);
111	        normalizeTelephone(ownerFieldsDto);
112	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
113	        rejectDuplicateHousehold(ownerFieldsDto);
114	        normalizeEmail(ownerFieldsDto);
115	        defaultRegistrationDate(ownerFieldsDto);
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        assignCustomerCode(owner);
119	        this.clinicService.saveOwner(owner);
120	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
121	        headers.setLocation(UriComponentsBuilder.newInstance()
122	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
123	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
129	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
130	        if (currentOwner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        normalizeEmail(ownerFieldsDto);
134	        currentOwner.setAddress(ownerFieldsDto.getAddress());
135	        currentOwner.setCity(ownerFieldsDto.getCity());
136	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
137	        currentOwner.setLastName(ownerFieldsDto.getLastName());
138	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
139	        currentOwner.setEmail(ownerFieldsDto.getEmail());
140	        this.clinicService.saveOwner(currentOwner);
141	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Transactional
146	    @Override
147	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        this.clinicService.deleteOwner(owner);
153	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
154	    }
