390	     * @return the collapsed, lower-cased value
391	     */
392	    private static String collapse(String value) {
393	        if (value == null) {
394	            return "";
395	        }
396	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
397	    }
